describe('Apply Promo Code and View Discounted Total', () => {
  beforeEach(() => {
    cy.visit('/checkout');
    cy.get('[data-testid="cart-items"]').should('be.visible');
  });

  it('should apply valid promo code and display discounted total', () => {
    // Get original total
    cy.get('[data-testid="original-total"]').then(($total) => {
      const originalTotal = parseFloat($total.text().replace(/[^0-9.]/g, ''));

      // Apply promo code
      cy.get('[data-testid="promo-code-input"]').type('SAVE20');
      cy.get('[data-testid="apply-promo-btn"]').click();

      // Verify success message
      cy.get('[data-testid="promo-success-message"]')
        .should('be.visible')
        .and('contain', 'Promo code applied successfully');

      // Verify discount is applied
      cy.get('[data-testid="discount-amount"]')
        .should('be.visible')
        .and('not.contain', '$0');

      // Verify discounted total is less than original
      cy.get('[data-testid="final-total"]').then(($finalTotal) => {
        const finalTotal = parseFloat($finalTotal.text().replace(/[^0-9.]/g, ''));
        expect(finalTotal).to.be.lessThan(originalTotal);
      });

      // Verify discount breakdown is visible
      cy.get('[data-testid="discount-breakdown"]').should('be.visible');
      cy.get('[data-testid="discount-percentage"]').should('contain', '20%');
    });
  });

  it('should display error message for invalid promo code', () => {
    // Attempt to apply invalid promo code
    cy.get('[data-testid="promo-code-input"]').type('INVALID123');
    cy.get('[data-testid="apply-promo-btn"]').click();

    // Verify error message
    cy.get('[data-testid="promo-error-message"]')
      .should('be.visible')
      .and('contain', 'Invalid or expired promo code');

    // Verify total remains unchanged
    cy.get('[data-testid="original-total"]').then(($originalTotal) => {
      const originalTotal = parseFloat($originalTotal.text().replace(/[^0-9.]/g, ''));

      cy.get('[data-testid="final-total"]').then(($finalTotal) => {
        const finalTotal = parseFloat($finalTotal.text().replace(/[^0-9.]/g, ''));
        expect(finalTotal).to.equal(originalTotal);
      });
    });

    // Verify no discount is shown
    cy.get('[data-testid="discount-amount"]').should('not.exist');
  });

  it('should remove promo code and restore original total', () => {
    // Apply valid promo code
    cy.get('[data-testid="promo-code-input"]').type('SAVE20');
    cy.get('[data-testid="apply-promo-btn"]').click();
    cy.get('[data-testid="promo-success-message"]').should('be.visible');

    // Get discounted total
    cy.get('[data-testid="final-total"]').then(($discountedTotal) => {
      const discountedTotal = parseFloat($discountedTotal.text().replace(/[^0-9.]/g, ''));

      // Remove promo code
      cy.get('[data-testid="remove-promo-btn"]').click();

      // Verify removal message
      cy.get('[data-testid="promo-removed-message"]')
        .should('be.visible')
        .and('contain', 'Promo code removed');

      // Verify total is restored to original
      cy.get('[data-testid="final-total"]').then(($restoredTotal) => {
        const restoredTotal = parseFloat($restoredTotal.text().replace(/[^0-9.]/g, ''));
        expect(restoredTotal).to.be.greaterThan(discountedTotal);
      });

      // Verify discount section is hidden
      cy.get('[data-testid="discount-breakdown"]').should('not.exist');
    });
  });

  it('should handle expired promo code gracefully', () => {
    // Apply expired promo code
    cy.get('[data-testid="promo-code-input"]').type('EXPIRED2023');
    cy.get('[data-testid="apply-promo-btn"]').click();

    // Verify specific expired message
    cy.get('[data-testid="promo-error-message"]')
      .should('be.visible')
      .and('contain', 'This promo code has expired');

    // Verify input field is still editable
    cy.get('[data-testid="promo-code-input"]')
      .should('be.enabled')
      .and('have.value', 'EXPIRED2023');

    // Verify user can clear and try another code
    cy.get('[data-testid="promo-code-input"]').clear();
    cy.get('[data-testid="promo-code-input"]').type('SAVE20');
    cy.get('[data-testid="apply-promo-btn"]').click();
    cy.get('[data-testid="promo-success-message"]').should('be.visible');
  });

  it('should apply promo code with minimum purchase requirement', () => {
    // Verify cart total meets minimum requirement
    cy.get('[data-testid="original-total"]').then(($total) => {
      const total = parseFloat($total.text().replace(/[^0-9.]/g, ''));

      if (total >= 50) {
        // Apply promo code with minimum requirement
        cy.get('[data-testid="promo-code-input"]').type('MIN50');
        cy.get('[data-testid="apply-promo-btn"]').click();
        cy.get('[data-testid="promo-success-message"]').should('be.visible');
      } else {
        // Apply promo code that requires minimum not met
        cy.get('[data-testid="promo-code-input"]').type('MIN50');
        cy.get('[data-testid="apply-promo-btn"]').click();
        cy.get('[data-testid="promo-error-message"]')
          .should('be.visible')
          .and('contain', 'Minimum purchase of $50 required');
      }
    });
  });
});
